window.FD_VARIANTS["original"] = [{"id":"original-001","variant":"original","source":"original","n":1,"seq":1,"total":null,"start":0,"end":15,"timecode":"00:00-00:15","track":null,"act":"I","actName":"THE WRONG WAY UP","beat":"","setting":"","camera":"","prompt":"Extreme close-up: the nameless man's cracked lips pull air that never seems to arrive. Dust sticks to the sweat above his mouth; a distant red light pulses behind his eyes. Slow, sickly push-in; grainy 1990s practical-effects horror, sepia and bruised purple.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-002","variant":"original","source":"original","n":2,"seq":2,"total":null,"start":15,"end":30,"timecode":"00:15-00:30","track":null,"act":"I","actName":"THE WRONG WAY UP","beat":"","setting":"","camera":"","prompt":"He jolts awake face-down on a checkerboard floor that bends upward into the horizon. He coughs grit, tries to stand, and his knees buckle. The camera stays low and imperfect, like a damaged VHS transfer.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-003","variant":"original","source":"original","n":3,"seq":3,"total":null,"start":30,"end":45,"timecode":"00:30-00:45","track":null,"act":"I","actName":"THE WRONG WAY UP","beat":"","setting":"","camera":"","prompt":"Wide reveal: an impossible cathedral-city surrounds him, its towers grown from stone, bone, and hollow eye-shaped windows. Staircases climb walls and curl into ceilings. The man is tiny in frame; no music, only wind through cavities.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-004","variant":"original","source":"original","n":4,"seq":4,"total":null,"start":45,"end":60,"timecode":"00:45-01:00","track":null,"act":"I","actName":"THE WRONG WAY UP","beat":"","setting":"","camera":"","prompt":"He scratches a crude arrow into a floor tile with a broken nail, marking the direction he came from. The tile slowly rotates until the arrow points straight down. He stares, then keeps moving.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-005","variant":"original","source":"original","n":5,"seq":5,"total":null,"start":60,"end":75,"timecode":"01:00-01:15","track":null,"act":"I","actName":"THE WRONG WAY UP","beat":"","setting":"","camera":"","prompt":"A corridor of arches stretches away, each arch smaller than the last, though the far end seems impossibly close. The man limps toward a rectangle of pale daylight that retreats with every step.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-006","variant":"original","source":"original","n":6,"seq":6,"total":null,"start":75,"end":90,"timecode":"01:15-01:30","track":null,"act":"I","actName":"THE WRONG WAY UP","beat":"","setting":"","camera":"","prompt":"He finds a doorway with a brass knob warm as skin. Turning it reveals the same corridor behind him, but an older version of his own footprints crosses the dust. He shuts it hard; the knob twitches like a finger.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-007","variant":"original","source":"original","n":7,"seq":7,"total":null,"start":90,"end":105,"timecode":"01:30-01:45","track":null,"act":"I","actName":"THE WRONG WAY UP","beat":"","setting":"","camera":"","prompt":"A staircase descends through the floor and emerges from the ceiling above him. He climbs down, gripping the rail; the camera rolls gradually until gravity feels uncertain. His coat snags, tears, and stays caught behind.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-008","variant":"original","source":"original","n":8,"seq":8,"total":null,"start":105,"end":120,"timecode":"01:45-02:00","track":null,"act":"I","actName":"THE WRONG WAY UP","beat":"","setting":"","camera":"","prompt":"He reaches a checkerboard plaza where the black squares sag like wet dough. One shoe sticks. He yanks it free with an ugly sucking sound and leaves the sole behind.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-009","variant":"original","source":"original","n":9,"seq":9,"total":null,"start":120,"end":135,"timecode":"02:00-02:15","track":null,"act":"I","actName":"THE WRONG WAY UP","beat":"","setting":"","camera":"","prompt":"At the plaza's center stands a payphone made of tarnished brass and teeth. He lifts the receiver; only his own shallow breathing comes through, half a second before he makes it.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-010","variant":"original","source":"original","n":10,"seq":10,"total":null,"start":135,"end":150,"timecode":"02:15-02:30","track":null,"act":"I","actName":"THE WRONG WAY UP","beat":"","setting":"","camera":"","prompt":"He presses every button. Each one lights a different distant window in the city. One window flashes three times, then goes dark. He pockets the receiver's severed cord as if it might be useful.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-011","variant":"original","source":"original","n":11,"seq":11,"total":null,"start":150,"end":165,"timecode":"02:30-02:45","track":null,"act":"I","actName":"THE WRONG WAY UP","beat":"","setting":"","camera":"","prompt":"A flock of pale, eyeless birds pours from a tower mouth and flies backward into the clouds. The man shields his face; one bird lands on his shoulder and whispers a single dry click before crumbling.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-012","variant":"original","source":"original","n":12,"seq":12,"total":null,"start":165,"end":180,"timecode":"02:45-03:00","track":null,"act":"I","actName":"THE WRONG WAY UP","beat":"","setting":"","camera":"","prompt":"He sees a thin strip of bright daylight between two distant towers. For the first time he hurries. The buildings bend inward, slowly sealing the gap like jaws.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-013","variant":"original","source":"original","n":13,"seq":13,"total":null,"start":180,"end":195,"timecode":"03:00-03:15","track":null,"act":"II","actName":"THE FIGMENTS","beat":"","setting":"","camera":"","prompt":"An alley narrows around him. Damp plaster bulges into the shape of a human cheek, then sinks back. He presses his palm to it; the wall is warm and gives a faint pulse.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-014","variant":"original","source":"original","n":14,"seq":14,"total":null,"start":195,"end":210,"timecode":"03:15-03:30","track":null,"act":"II","actName":"THE FIGMENTS","beat":"","setting":"","camera":"","prompt":"A child-sized figure stands at the far end, wrapped in the man's oversized coat. Its head is a smooth oval with a tiny locked mouth. It holds out a wet matchbook.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-015","variant":"original","source":"original","n":15,"seq":15,"total":null,"start":210,"end":225,"timecode":"03:30-03:45","track":null,"act":"II","actName":"THE FIGMENTS","beat":"","setting":"","camera":"","prompt":"He takes the matchbook. Inside, every match has been snapped in half. The small figure points at his bare feet, then walks backward through a wall without turning around.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-016","variant":"original","source":"original","n":16,"seq":16,"total":null,"start":225,"end":240,"timecode":"03:45-04:00","track":null,"act":"II","actName":"THE FIGMENTS","beat":"","setting":"","camera":"","prompt":"The man follows into a room filled with ankle-deep black water. A second figure sits at a school desk: a thin, many-jointed version of him with a paper bag over its head, scratching at a blank page.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-017","variant":"original","source":"original","n":17,"seq":17,"total":null,"start":240,"end":255,"timecode":"04:00-04:15","track":null,"act":"II","actName":"THE FIGMENTS","beat":"","setting":"","camera":"","prompt":"The paper-bag figure pushes the page toward him. Under the surface, letters press upward but never become readable. He tries to write; the pencil breaks in his fingers.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-018","variant":"original","source":"original","n":18,"seq":18,"total":null,"start":255,"end":270,"timecode":"04:15-04:30","track":null,"act":"II","actName":"THE FIGMENTS","beat":"","setting":"","camera":"","prompt":"The figure removes the bag. Its face is the man's own, younger and exhausted, with one eye sealed shut by old adhesive. It does not accuse him. It simply waits.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-019","variant":"original","source":"original","n":19,"seq":19,"total":null,"start":270,"end":285,"timecode":"04:30-04:45","track":null,"act":"II","actName":"THE FIGMENTS","beat":"","setting":"","camera":"","prompt":"He sits opposite it. Water drips from his sleeves onto the page. After a long beat, he places the broken pencil beside the figure and backs away, leaving the page blank.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-020","variant":"original","source":"original","n":20,"seq":20,"total":null,"start":285,"end":300,"timecode":"04:45-05:00","track":null,"act":"II","actName":"THE FIGMENTS","beat":"","setting":"","camera":"","prompt":"The room's water drains through the checkerboard floor. The younger figure collapses into a puddle of sepia sludge threaded with violet light. The man does not look away until the last ripple stops.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-021","variant":"original","source":"original","n":21,"seq":21,"total":null,"start":300,"end":315,"timecode":"05:00-05:15","track":null,"act":"II","actName":"THE FIGMENTS","beat":"","setting":"","camera":"","prompt":"He enters a forest of spiraling fleshy trunks, each bark surface covered in tiny closed mouths. The branches twist slowly as if trying to remember a shape. No leaves; only hanging strips of dark membrane.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-022","variant":"original","source":"original","n":22,"seq":22,"total":null,"start":315,"end":330,"timecode":"05:15-05:30","track":null,"act":"II","actName":"THE FIGMENTS","beat":"","setting":"","camera":"","prompt":"A tall creature with too many elbows crawls down a trunk. Its chest opens like a filing cabinet, revealing dozens of tiny drawers. It offers him one drawer, labeled only by a dented key.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-023","variant":"original","source":"original","n":23,"seq":23,"total":null,"start":330,"end":345,"timecode":"05:30-05:45","track":null,"act":"II","actName":"THE FIGMENTS","beat":"","setting":"","camera":"","prompt":"He opens it. Inside is a small, ordinary object: a cracked ceramic cup with a brown ring at the bottom. His hand shakes as he turns it over.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-024","variant":"original","source":"original","n":24,"seq":24,"total":null,"start":345,"end":360,"timecode":"05:45-06:00","track":null,"act":"II","actName":"THE FIGMENTS","beat":"","setting":"","camera":"","prompt":"The creature mimics his posture, then exaggerates every tremor. He tries to snatch the cup; the creature folds its limbs around it and waits. The struggle is clumsy, breathless, and small.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-025","variant":"original","source":"original","n":25,"seq":25,"total":null,"start":360,"end":375,"timecode":"06:00-06:15","track":null,"act":"II","actName":"THE FIGMENTS","beat":"","setting":"","camera":"","prompt":"He stops pulling. The creature places the cup in his hands and presses its forehead against his. Their skin briefly shares the same seams and bruises.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-026","variant":"original","source":"original","n":26,"seq":26,"total":null,"start":375,"end":390,"timecode":"06:15-06:30","track":null,"act":"II","actName":"THE FIGMENTS","beat":"","setting":"","camera":"","prompt":"The creature unthreads into wet ribbons of black-brown matter and faint neon purple. The cup remains solid. The man puts it inside his torn coat and continues.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-027","variant":"original","source":"original","n":27,"seq":27,"total":null,"start":390,"end":405,"timecode":"06:30-06:45","track":null,"act":"II","actName":"THE FIGMENTS","beat":"","setting":"","camera":"","prompt":"A long gallery displays hundreds of doors, each with a different kind of lock. Behind one, something scratches; behind another, a muffled laugh cuts off abruptly. He tries each handle without choosing.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-028","variant":"original","source":"original","n":28,"seq":28,"total":null,"start":405,"end":420,"timecode":"06:45-07:00","track":null,"act":"II","actName":"THE FIGMENTS","beat":"","setting":"","camera":"","prompt":"One door has no lock, only a shallow handprint in the wood. He presses his palm into it. The door swings inward onto a hospital corridor with no visible end.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-029","variant":"original","source":"original","n":29,"seq":29,"total":null,"start":420,"end":435,"timecode":"07:00-07:15","track":null,"act":"II","actName":"THE FIGMENTS","beat":"","setting":"","camera":"","prompt":"At the corridor's center lies a gurney carrying a bundled shape that rises and falls with his breath. The man backs away, bumping into a wall that wasn't there a moment ago.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-030","variant":"original","source":"original","n":30,"seq":30,"total":null,"start":435,"end":450,"timecode":"07:15-07:30","track":null,"act":"II","actName":"THE FIGMENTS","beat":"","setting":"","camera":"","prompt":"The bundle's sheet slips. Underneath is not a body but a mass of hands, each gripping a different part of the sheet. The man kneels and gently releases one finger at a time.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-031","variant":"original","source":"original","n":31,"seq":31,"total":null,"start":450,"end":465,"timecode":"07:30-07:45","track":null,"act":"II","actName":"THE FIGMENTS","beat":"","setting":"","camera":"","prompt":"The hands loosen. They sink through the gurney into the floor, leaving a single indentation shaped like a sleeping face. The corridor lights go out one by one behind him.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-032","variant":"original","source":"original","n":31,"seq":32,"total":null,"start":450,"end":465,"timecode":"07:30-07:45","track":null,"act":"III","actName":"THE BODY OF THE DREAM","beat":"","setting":"","camera":"","prompt":"He emerges onto a desert of warped checkerboard tiles, each tile tilted at a different angle. Heat ripples sideways. Far away, an enormous rib cage arches over the horizon like a bridge.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":"Source numbering anomaly: this entry is labelled 031 a second time in the PDF (the first 031 entry is the previous generation). Its true sequence position is 32."},{"id":"original-033","variant":"original","source":"original","n":32,"seq":33,"total":null,"start":465,"end":480,"timecode":"07:45-08:00","track":null,"act":"III","actName":"THE BODY OF THE DREAM","beat":"","setting":"","camera":"","prompt":"He walks across the desert, stumbling as the squares shift under his weight. His feet bleed, but the blood turns to dull gold dust before it hits the ground.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-034","variant":"original","source":"original","n":33,"seq":34,"total":null,"start":480,"end":495,"timecode":"08:00-08:15","track":null,"act":"III","actName":"THE BODY OF THE DREAM","beat":"","setting":"","camera":"","prompt":"A wind begins carrying scraps of paper across the plain. Each scrap bears a partial diagram of a human body, incomplete and smudged. He tries to assemble them; the wind tears the pieces away.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-035","variant":"original","source":"original","n":34,"seq":35,"total":null,"start":495,"end":510,"timecode":"08:15-08:30","track":null,"act":"III","actName":"THE BODY OF THE DREAM","beat":"","setting":"","camera":"","prompt":"A hulking figure rises from the sand, its torso a swollen clock with no hands. Its face is hidden behind a cracked hospital mask. Every step makes a damp, irregular ticking.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-036","variant":"original","source":"original","n":35,"seq":36,"total":null,"start":510,"end":525,"timecode":"08:30-08:45","track":null,"act":"III","actName":"THE BODY OF THE DREAM","beat":"","setting":"","camera":"","prompt":"The clock-bodied figure blocks the path but never attacks. The man shoves it; his palms sink into its soft torso. Beneath the mask, a tiny mouth struggles to form a word and fails.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-037","variant":"original","source":"original","n":36,"seq":37,"total":null,"start":525,"end":540,"timecode":"08:45-09:00","track":null,"act":"III","actName":"THE BODY OF THE DREAM","beat":"","setting":"","camera":"","prompt":"He withdraws his hands and steadies the figure by its shoulders. The ticking slows. He leans his forehead against the mask, breathing in time with the failing rhythm.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-038","variant":"original","source":"original","n":37,"seq":38,"total":null,"start":540,"end":555,"timecode":"09:00-09:15","track":null,"act":"III","actName":"THE BODY OF THE DREAM","beat":"","setting":"","camera":"","prompt":"The figure folds into itself like a wet tent. A burst of sepia dust drifts across the tiles. Under it, a narrow path of clean white squares appears, leading toward the rib-cage bridge.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-039","variant":"original","source":"original","n":38,"seq":39,"total":null,"start":555,"end":570,"timecode":"09:15-09:30","track":null,"act":"III","actName":"THE BODY OF THE DREAM","beat":"","setting":"","camera":"","prompt":"He crosses the bridge. Between the ribs hang hundreds of little red doors, opening and closing without sound. Something behind each door presses outward, then retreats.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-040","variant":"original","source":"original","n":39,"seq":40,"total":null,"start":570,"end":585,"timecode":"09:30-09:45","track":null,"act":"III","actName":"THE BODY OF THE DREAM","beat":"","setting":"","camera":"","prompt":"One red door hangs at his eye level. He opens it and finds a cramped apartment kitchen, yellowed linoleum, a dead fluorescent tube, and a tap dripping into a chipped mug.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-041","variant":"original","source":"original","n":40,"seq":41,"total":null,"start":585,"end":600,"timecode":"09:45-10:00","track":null,"act":"III","actName":"THE BODY OF THE DREAM","beat":"","setting":"","camera":"","prompt":"He stands at the sink, trying to turn the tap off. The handle spins freely. Water rises despite the drain, reaching his wrists, then elbows. His breath becomes ragged and audible.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-042","variant":"original","source":"original","n":41,"seq":42,"total":null,"start":600,"end":615,"timecode":"10:00-10:15","track":null,"act":"III","actName":"THE BODY OF THE DREAM","beat":"","setting":"","camera":"","prompt":"A figure made of damp towels and tangled hair sits at the kitchen table. It pushes a dry towel toward him, then pulls it back whenever he reaches. The cruelty is petty, almost bored.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-043","variant":"original","source":"original","n":42,"seq":43,"total":null,"start":615,"end":630,"timecode":"10:15-10:30","track":null,"act":"III","actName":"THE BODY OF THE DREAM","beat":"","setting":"","camera":"","prompt":"He stops reaching. He sits on the floor, soaked, and lets the water rise around his chest. The towel figure finally drapes the towel over his shoulders; the water falls through the tiles in a single gulp.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-044","variant":"original","source":"original","n":43,"seq":44,"total":null,"start":630,"end":645,"timecode":"10:30-10:45","track":null,"act":"III","actName":"THE BODY OF THE DREAM","beat":"","setting":"","camera":"","prompt":"The kitchen shrivels into a paper-thin doorway. Beyond it, the desert has become a sea of checkerboard dunes. The man squeezes through sideways, tearing his coat on the frame.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-045","variant":"original","source":"original","n":44,"seq":45,"total":null,"start":645,"end":660,"timecode":"10:45-11:00","track":null,"act":"III","actName":"THE BODY OF THE DREAM","beat":"","setting":"","camera":"","prompt":"A gigantic eye opens beneath the sand. The pupil tracks him under the surface. He freezes; the eye closes, and a hill rises where it had been, leaving a damp circular scar.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-046","variant":"original","source":"original","n":45,"seq":46,"total":null,"start":660,"end":675,"timecode":"11:00-11:15","track":null,"act":"III","actName":"THE BODY OF THE DREAM","beat":"","setting":"","camera":"","prompt":"He digs at the scar with his bare hands. Under the crust he finds a small mirror clouded with age. His reflection appears older, then younger, then missing pieces, as if frames were lost from a tape.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-047","variant":"original","source":"original","n":46,"seq":47,"total":null,"start":675,"end":690,"timecode":"11:15-11:30","track":null,"act":"III","actName":"THE BODY OF THE DREAM","beat":"","setting":"","camera":"","prompt":"He wipes the mirror with his sleeve. For one clear instant he sees his own tired face, no monster, no revelation. He holds it close until the glass fogs from his breath.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-048","variant":"original","source":"original","n":47,"seq":48,"total":null,"start":690,"end":705,"timecode":"11:30-11:45","track":null,"act":"III","actName":"THE BODY OF THE DREAM","beat":"","setting":"","camera":"","prompt":"The mirror cracks in a crooked line. He doesn't throw it away. He wraps it in a strip torn from his coat and tucks it beside the cup.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-049","variant":"original","source":"original","n":48,"seq":49,"total":null,"start":705,"end":720,"timecode":"11:45-12:00","track":null,"act":"III","actName":"THE BODY OF THE DREAM","beat":"","setting":"","camera":"","prompt":"At the far edge of the desert, a forest grows upside down from a black sky. Its roots hang like veins and drip violet light into a ravine. He begins the descent with no visible path.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-050","variant":"original","source":"original","n":49,"seq":50,"total":null,"start":720,"end":735,"timecode":"12:00-12:15","track":null,"act":"IV","actName":"THE HOUSE OF REGRET","beat":"","setting":"","camera":"","prompt":"He descends into the ravine by grabbing roots that flex under his weight. Several snap. He lands hard on a shelf of stone, grunts, and takes time before trying again.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-051","variant":"original","source":"original","n":50,"seq":51,"total":null,"start":735,"end":750,"timecode":"12:15-12:30","track":null,"act":"IV","actName":"THE HOUSE OF REGRET","beat":"","setting":"","camera":"","prompt":"The shelf opens into a house made from overlapping hallways. Wallpaper peels in long strips that reveal more wallpaper underneath. Every room contains the same small table, moved a few inches.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-052","variant":"original","source":"original","n":51,"seq":52,"total":null,"start":750,"end":765,"timecode":"12:30-12:45","track":null,"act":"IV","actName":"THE HOUSE OF REGRET","beat":"","setting":"","camera":"","prompt":"He enters a dining room. Across the table sits a faceless figure wearing his coat from years ago, sleeves too short. A cold meal has dried into the plate. Two chairs scrape though nobody moves.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-053","variant":"original","source":"original","n":52,"seq":53,"total":null,"start":765,"end":780,"timecode":"12:45-13:00","track":null,"act":"IV","actName":"THE HOUSE OF REGRET","beat":"","setting":"","camera":"","prompt":"The figure taps the empty chair. He sits. Neither touches the food. A ceiling leak drips into the plate, one drop at a time, with unbearable regularity.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-054","variant":"original","source":"original","n":53,"seq":54,"total":null,"start":780,"end":795,"timecode":"13:00-13:15","track":null,"act":"IV","actName":"THE HOUSE OF REGRET","beat":"","setting":"","camera":"","prompt":"He pushes the plate away. The figure pushes it back. They repeat the gesture until the plate chips and a shard cuts his thumb. He wraps the thumb in a napkin without looking up.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-055","variant":"original","source":"original","n":54,"seq":55,"total":null,"start":795,"end":810,"timecode":"13:15-13:30","track":null,"act":"IV","actName":"THE HOUSE OF REGRET","beat":"","setting":"","camera":"","prompt":"The figure points to the blood on the napkin, then to its own blank face. The man slowly places the napkin between them. The figure's face dents inward like soft wax.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-056","variant":"original","source":"original","n":55,"seq":56,"total":null,"start":810,"end":825,"timecode":"13:30-13:45","track":null,"act":"IV","actName":"THE HOUSE OF REGRET","beat":"","setting":"","camera":"","prompt":"The dining room tilts. Furniture slides into a dark corner, and the figure melts through the floor. The man remains seated until the table cracks down the middle.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-057","variant":"original","source":"original","n":56,"seq":57,"total":null,"start":825,"end":840,"timecode":"13:45-14:00","track":null,"act":"IV","actName":"THE HOUSE OF REGRET","beat":"","setting":"","camera":"","prompt":"A staircase leads into a bedroom whose ceiling is too low to stand beneath. On the bed lies a mound of coats, each one damp and heavier than the last. A shallow depression marks where a body should be.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-058","variant":"original","source":"original","n":57,"seq":58,"total":null,"start":840,"end":855,"timecode":"14:00-14:15","track":null,"act":"IV","actName":"THE HOUSE OF REGRET","beat":"","setting":"","camera":"","prompt":"He lifts the top coat. Underneath are dozens more, stitched together at the cuffs. He tries to pull one free and gets tangled, rolling off the bed onto the floor.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-059","variant":"original","source":"original","n":58,"seq":59,"total":null,"start":855,"end":870,"timecode":"14:15-14:30","track":null,"act":"IV","actName":"THE HOUSE OF REGRET","beat":"","setting":"","camera":"","prompt":"He lies still, cheek against dusty boards. The coats twitch above him like sleeping animals. He crawls out of their reach rather than fighting them.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-060","variant":"original","source":"original","n":59,"seq":60,"total":null,"start":870,"end":885,"timecode":"14:30-14:45","track":null,"act":"IV","actName":"THE HOUSE OF REGRET","beat":"","setting":"","camera":"","prompt":"A wardrobe stands open, showing a hallway inside. At the far end, a thin figure scrubs the same stain from a wall with a dry brush. Its shoulders jerk with each useless stroke.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-061","variant":"original","source":"original","n":60,"seq":61,"total":null,"start":885,"end":900,"timecode":"14:45-15:00","track":null,"act":"IV","actName":"THE HOUSE OF REGRET","beat":"","setting":"","camera":"","prompt":"The man takes the brush. The stain returns as soon as he scrubs it. He stops, holds the brush out, and lets the figure decide whether to take it back.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-062","variant":"original","source":"original","n":61,"seq":62,"total":null,"start":900,"end":915,"timecode":"15:00-15:15","track":null,"act":"IV","actName":"THE HOUSE OF REGRET","beat":"","setting":"","camera":"","prompt":"The figure's fingers close around his wrist. For a moment their arms look joined at the elbow, one limb with two hands. Neither pulls away.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-063","variant":"original","source":"original","n":62,"seq":63,"total":null,"start":915,"end":930,"timecode":"15:15-15:30","track":null,"act":"IV","actName":"THE HOUSE OF REGRET","beat":"","setting":"","camera":"","prompt":"The stain spreads across the wall, then peels off in a single sheet and drops like old skin. Behind it is bare brick, stained but ordinary. The figure dissolves into the grout.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-064","variant":"original","source":"original","n":63,"seq":64,"total":null,"start":930,"end":945,"timecode":"15:30-15:45","track":null,"act":"IV","actName":"THE HOUSE OF REGRET","beat":"","setting":"","camera":"","prompt":"He passes through the wardrobe hallway and reaches a nursery with no toys, only a mobile made of tiny teeth. It rotates slowly though the air is still.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-065","variant":"original","source":"original","n":64,"seq":65,"total":null,"start":945,"end":960,"timecode":"15:45-16:00","track":null,"act":"IV","actName":"THE HOUSE OF REGRET","beat":"","setting":"","camera":"","prompt":"A childlike shadow rocks in an empty chair. Its feet do not reach the floor. The man sits on the boards opposite it, leaving the distance between them untouched.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-066","variant":"original","source":"original","n":65,"seq":66,"total":null,"start":960,"end":975,"timecode":"16:00-16:15","track":null,"act":"IV","actName":"THE HOUSE OF REGRET","beat":"","setting":"","camera":"","prompt":"The shadow slides a small object across the floor: a key with its teeth worn smooth. He takes it but doesn't try to use it. The chair stops rocking.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-067","variant":"original","source":"original","n":66,"seq":67,"total":null,"start":975,"end":990,"timecode":"16:15-16:30","track":null,"act":"IV","actName":"THE HOUSE OF REGRET","beat":"","setting":"","camera":"","prompt":"The nursery walls peel away, revealing the vast cathedral again. The man steps out carrying the key, cup, and wrapped mirror. His coat is almost gone; his gait is worse.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-068","variant":"original","source":"original","n":67,"seq":68,"total":null,"start":990,"end":1005,"timecode":"16:30-16:45","track":null,"act":"IV","actName":"THE HOUSE OF REGRET","beat":"","setting":"","camera":"","prompt":"Behind him, the nursery folds shut like a book. A single tooth drops onto the floor and rolls in a circle until it falls through a crack.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-069","variant":"original","source":"original","n":69,"seq":69,"total":null,"start":1020,"end":1035,"timecode":"17:00-17:15","track":null,"act":"V","actName":"THE EDGE THAT MOVES","beat":"","setting":"","camera":"","prompt":"He reaches a tower whose outer wall is made of black glass. Inside, hundreds of staircases climb in different directions, crossing through one another without touching.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-070","variant":"original","source":"original","n":70,"seq":70,"total":null,"start":1035,"end":1050,"timecode":"17:15-17:30","track":null,"act":"V","actName":"THE EDGE THAT MOVES","beat":"","setting":"","camera":"","prompt":"He climbs one flight. A landing opens onto the same stairwell from above. He tries another. The steps flatten into a ramp and slide him back to the bottom.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-071","variant":"original","source":"original","n":71,"seq":71,"total":null,"start":1050,"end":1065,"timecode":"17:30-17:45","track":null,"act":"V","actName":"THE EDGE THAT MOVES","beat":"","setting":"","camera":"","prompt":"He sits against the wall, exhausted, picking a loose thread from his sleeve. The thread keeps coming, longer than the coat. He wraps it around his wrist to mark the place.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-072","variant":"original","source":"original","n":72,"seq":72,"total":null,"start":1065,"end":1080,"timecode":"17:45-18:00","track":null,"act":"V","actName":"THE EDGE THAT MOVES","beat":"","setting":"","camera":"","prompt":"A distant bell rings from inside his chest. He presses his ear to his sternum; the sound repeats, followed by a faint knocking from somewhere beneath the floor.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-073","variant":"original","source":"original","n":73,"seq":73,"total":null,"start":1080,"end":1095,"timecode":"18:00-18:15","track":null,"act":"V","actName":"THE EDGE THAT MOVES","beat":"","setting":"","camera":"","prompt":"He finds a narrow stair marked by no sign, barely wide enough for his feet. He climbs sideways, using the wall for balance. The camera follows too close, sometimes losing his face.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-074","variant":"original","source":"original","n":74,"seq":74,"total":null,"start":1095,"end":1110,"timecode":"18:15-18:30","track":null,"act":"V","actName":"THE EDGE THAT MOVES","beat":"","setting":"","camera":"","prompt":"At the top is a room with a single window overlooking a bright, flat horizon. He reaches for the latch; the window swings open onto another room, facing him from the other side.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-075","variant":"original","source":"original","n":75,"seq":75,"total":null,"start":1110,"end":1125,"timecode":"18:30-18:45","track":null,"act":"V","actName":"THE EDGE THAT MOVES","beat":"","setting":"","camera":"","prompt":"His own silhouette stands in the opposite room, motionless, its head bowed. He pounds the glass. The silhouette lifts its head a beat later and copies him badly.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-076","variant":"original","source":"original","n":76,"seq":76,"total":null,"start":1125,"end":1140,"timecode":"18:45-19:00","track":null,"act":"V","actName":"THE EDGE THAT MOVES","beat":"","setting":"","camera":"","prompt":"He stops moving. The silhouette continues for a moment, then hangs limp. A seam opens down its chest, revealing a jumble of clocks, teeth, keys, and wet paper.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-077","variant":"original","source":"original","n":77,"seq":77,"total":null,"start":1140,"end":1155,"timecode":"19:00-19:15","track":null,"act":"V","actName":"THE EDGE THAT MOVES","beat":"","setting":"","camera":"","prompt":"He steps through the window frame into the opposite room. The silhouette is only his coat hanging from a nail. He takes the coat down, folds it once, and leaves it on the floor.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-078","variant":"original","source":"original","n":78,"seq":78,"total":null,"start":1155,"end":1170,"timecode":"19:15-19:30","track":null,"act":"V","actName":"THE EDGE THAT MOVES","beat":"","setting":"","camera":"","prompt":"A low tunnel leads beneath the tower. Its walls contract and expand like tired lungs. He crawls, scraping his knuckles, and pauses to cough black dust from his throat.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-079","variant":"original","source":"original","n":79,"seq":79,"total":null,"start":1170,"end":1185,"timecode":"19:30-19:45","track":null,"act":"V","actName":"THE EDGE THAT MOVES","beat":"","setting":"","camera":"","prompt":"The tunnel opens into a room of suspended doorframes. Each frame shows a different false exit: a sunlit field, a city street, a hospital room, a blank white void. None has a floor beyond it.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-080","variant":"original","source":"original","n":80,"seq":80,"total":null,"start":1185,"end":1200,"timecode":"19:45-20:00","track":null,"act":"V","actName":"THE EDGE THAT MOVES","beat":"","setting":"","camera":"","prompt":"He approaches the sunlit field. Warm wind touches his face; the grass smells almost real. He puts one foot through and finds only a vertical drop. He pulls back, shaking.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-081","variant":"original","source":"original","n":81,"seq":81,"total":null,"start":1200,"end":1215,"timecode":"20:00-20:15","track":null,"act":"V","actName":"THE EDGE THAT MOVES","beat":"","setting":"","camera":"","prompt":"The hospital doorway leaks a steady fluorescent buzz. Through it, a monitor draws a thin green line, then a jagged spike. He grips the frame until his fingers whiten but cannot cross.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-082","variant":"original","source":"original","n":82,"seq":82,"total":null,"start":1215,"end":1230,"timecode":"20:15-20:30","track":null,"act":"V","actName":"THE EDGE THAT MOVES","beat":"","setting":"","camera":"","prompt":"The blank white doorway has no sound at all. He stands before it, terrified by the absence more than the monsters. He raises the worn key, though it has no teeth left.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-083","variant":"original","source":"original","n":83,"seq":83,"total":null,"start":1230,"end":1245,"timecode":"20:30-20:45","track":null,"act":"V","actName":"THE EDGE THAT MOVES","beat":"","setting":"","camera":"","prompt":"He inserts the key into empty air. A lock clicks somewhere behind his ribs. The white frame shudders but does not open; hairline cracks spread through every false exit.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-084","variant":"original","source":"original","n":84,"seq":84,"total":null,"start":1245,"end":1260,"timecode":"20:45-21:00","track":null,"act":"V","actName":"THE EDGE THAT MOVES","beat":"","setting":"","camera":"","prompt":"The doors collapse inward, not outward. The room fills with scraps of landscape, hospital tile, grass, and plaster, all swirling around his legs. He shields his face and keeps standing.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-085","variant":"original","source":"original","n":85,"seq":85,"total":null,"start":1260,"end":1275,"timecode":"21:00-21:15","track":null,"act":"V","actName":"THE EDGE THAT MOVES","beat":"","setting":"","camera":"","prompt":"When the debris settles, the man stands in a plain, unfinished room. No creature waits here. A low hum comes from beneath the floor, steady and mechanical.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-086","variant":"original","source":"original","n":86,"seq":86,"total":null,"start":1275,"end":1290,"timecode":"21:15-21:30","track":null,"act":"V","actName":"THE EDGE THAT MOVES","beat":"","setting":"","camera":"","prompt":"He kneels and places the cup, wrapped mirror, and smooth key in a row. He looks at them as if they belong to someone he used to know. Then he gets up and follows the hum.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-087","variant":"original","source":"original","n":87,"seq":87,"total":null,"start":1290,"end":1305,"timecode":"21:30-21:45","track":null,"act":"V","actName":"THE EDGE THAT MOVES","beat":"","setting":"","camera":"","prompt":"The floor slopes down into a circular shaft lined with old plaster. He descends a narrow iron ladder, each rung giving a small metallic complaint. The light above shrinks to a dirty coin.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-088","variant":"original","source":"original","n":88,"seq":88,"total":null,"start":1305,"end":1320,"timecode":"21:45-22:00","track":null,"act":"V","actName":"THE EDGE THAT MOVES","beat":"","setting":"","camera":"","prompt":"At the bottom, a corridor of hospital-green tiles stretches toward a half-open door. He touches the wall; it is cold, flat, and unremarkable. He moves toward it without hurrying.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-089","variant":"original","source":"original","n":89,"seq":89,"total":null,"start":1320,"end":1335,"timecode":"22:00-22:15","track":null,"act":"V","actName":"THE EDGE THAT MOVES","beat":"","setting":"","camera":"","prompt":"The door opens onto an empty ward. Curtains stir though the windows are sealed. Beyond one curtain, a shape rises and falls with a shallow, mechanical rhythm.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-090","variant":"original","source":"original","n":90,"seq":90,"total":null,"start":1335,"end":1350,"timecode":"22:15-22:30","track":null,"act":"V","actName":"THE EDGE THAT MOVES","beat":"","setting":"","camera":"","prompt":"He pulls the curtain aside. A body lies beneath white sheets, face obscured by tubes and tape. The man recoils, then steps close enough to see the hand resting on the blanket.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-091","variant":"original","source":"original","n":91,"seq":91,"total":null,"start":1350,"end":1365,"timecode":"22:30-22:45","track":null,"act":"V","actName":"THE EDGE THAT MOVES","beat":"","setting":"","camera":"","prompt":"He compares that hand to his own: same scar, same crooked nail, same tremor. He lays his palm beside it, not touching. The monitor's green line keeps crawling.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-092","variant":"original","source":"original","n":91,"seq":92,"total":null,"start":1350,"end":1365,"timecode":"22:30-22:45","track":null,"act":"VI","actName":"NO GRAND AWAKENING","beat":"","setting":"","camera":"","prompt":"The ward lights flicker. The walls ripple back into organic stone for a second, then settle. The man backs toward the door, unsure whether he has reached an exit or another trick.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":"Source numbering anomaly: this entry is labelled 091 a second time in the PDF (the first 091 entry is the previous generation). Its true sequence position is 92."},{"id":"original-093","variant":"original","source":"original","n":92,"seq":93,"total":null,"start":1365,"end":1380,"timecode":"22:45-23:00","track":null,"act":"VI","actName":"NO GRAND AWAKENING","beat":"","setting":"","camera":"","prompt":"A small Figment crawls from beneath the bed: a knot of elbows, damp hair, and child-sized hands. It holds the cracked ceramic cup. The man kneels rather than reaching for it.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-094","variant":"original","source":"original","n":93,"seq":94,"total":null,"start":1380,"end":1395,"timecode":"23:00-23:15","track":null,"act":"VI","actName":"NO GRAND AWAKENING","beat":"","setting":"","camera":"","prompt":"The Figment places the cup between his shoes. Its many hands uncurl, one by one. He recognizes the gesture from the forest creature and lets the silence stand.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-095","variant":"original","source":"original","n":94,"seq":95,"total":null,"start":1395,"end":1410,"timecode":"23:15-23:30","track":null,"act":"VI","actName":"NO GRAND AWAKENING","beat":"","setting":"","camera":"","prompt":"The creature's limbs soften into dark sludge threaded with violet light. The sludge seeps into the grout. No sting, no victory music, no reward-only a faint warmth in the floor.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-096","variant":"original","source":"original","n":95,"seq":96,"total":null,"start":1410,"end":1425,"timecode":"23:30-23:45","track":null,"act":"VI","actName":"NO GRAND AWAKENING","beat":"","setting":"","camera":"","prompt":"The monitor's rhythm stutters. The man grips the bedrail until his fingers hurt. He looks at the covered face, then at the exit, caught between two ordinary acts.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-097","variant":"original","source":"original","n":96,"seq":97,"total":null,"start":1425,"end":1440,"timecode":"23:45-24:00","track":null,"act":"VI","actName":"NO GRAND AWAKENING","beat":"","setting":"","camera":"","prompt":"He pulls a chair beside the bed and sits. The chair squeals against the tile. He does not remove the tubes or shake the body; he simply stays, shoulders sagging.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-098","variant":"original","source":"original","n":97,"seq":98,"total":null,"start":1440,"end":1455,"timecode":"24:00-24:15","track":null,"act":"VI","actName":"NO GRAND AWAKENING","beat":"","setting":"","camera":"","prompt":"Time drags. A curtain taps the radiator. The man rubs his thumb over the old scar on his hand. The monitor keeps its indifferent rhythm.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-099","variant":"original","source":"original","n":98,"seq":99,"total":null,"start":1455,"end":1470,"timecode":"24:15-24:30","track":null,"act":"VI","actName":"NO GRAND AWAKENING","beat":"","setting":"","camera":"","prompt":"The covered hand twitches once. He rises too quickly, knocks the chair over, and catches himself on the bedrail. Nothing else moves.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-100","variant":"original","source":"original","n":99,"seq":100,"total":null,"start":1470,"end":1485,"timecode":"24:30-24:45","track":null,"act":"VI","actName":"NO GRAND AWAKENING","beat":"","setting":"","camera":"","prompt":"He waits for a second twitch. None comes. His breath shudders; he picks the chair up and sets it back where it was, carefully aligning its legs with the floor tiles.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-101","variant":"original","source":"original","n":100,"seq":101,"total":null,"start":1485,"end":1500,"timecode":"24:45-25:00","track":null,"act":"VI","actName":"NO GRAND AWAKENING","beat":"","setting":"","camera":"","prompt":"The ward stretches into an endless corridor. Doorways bloom along the walls, each showing a fragment of the places he crossed. He turns away from them and faces the far end.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-102","variant":"original","source":"original","n":101,"seq":102,"total":null,"start":1500,"end":1515,"timecode":"25:00-25:15","track":null,"act":"VI","actName":"NO GRAND AWAKENING","beat":"","setting":"","camera":"","prompt":"At the far end, a red exit sign hangs upside down. Its light pulses weakly. He walks toward it, dragging one foot, never looking back at the open doors.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-103","variant":"original","source":"original","n":102,"seq":103,"total":null,"start":1515,"end":1530,"timecode":"25:15-25:30","track":null,"act":"VI","actName":"NO GRAND AWAKENING","beat":"","setting":"","camera":"","prompt":"The corridor begins to fold. The ceiling lowers, floor rises, and the walls curl around him like a closing shell. He presses forward on hands and knees.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-104","variant":"original","source":"original","n":103,"seq":104,"total":null,"start":1530,"end":1545,"timecode":"25:30-25:45","track":null,"act":"VI","actName":"NO GRAND AWAKENING","beat":"","setting":"","camera":"","prompt":"He reaches the exit sign and finds no door, only a patch of bare wall with a small, dark seam. He runs his fingers along it until a splinter catches under his nail.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-105","variant":"original","source":"original","n":104,"seq":105,"total":null,"start":1545,"end":1560,"timecode":"25:45-26:00","track":null,"act":"VI","actName":"NO GRAND AWAKENING","beat":"","setting":"","camera":"","prompt":"He digs at the seam with the broken nail. The plaster crumbles. Behind it is not daylight but a narrow line of warm, living darkness, breathing softly.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-106","variant":"original","source":"original","n":105,"seq":106,"total":null,"start":1560,"end":1575,"timecode":"26:00-26:15","track":null,"act":"VI","actName":"NO GRAND AWAKENING","beat":"","setting":"","camera":"","prompt":"He leans his forehead against the crack. A low human breath answers from the other side, not words. His face tightens as if he recognizes the rhythm without knowing why.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-107","variant":"original","source":"original","n":106,"seq":107,"total":null,"start":1575,"end":1590,"timecode":"26:15-26:30","track":null,"act":"VI","actName":"NO GRAND AWAKENING","beat":"","setting":"","camera":"","prompt":"He widens the crack with both hands. The wall tears like wet paper, exposing a thin slit of pale light. The entire structure groans; distant towers begin to slump.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-108","variant":"original","source":"original","n":107,"seq":108,"total":null,"start":1590,"end":1605,"timecode":"26:30-26:45","track":null,"act":"VI","actName":"NO GRAND AWAKENING","beat":"","setting":"","camera":"","prompt":"The checkerboard floor breaks into floating tiles. The man falls to one knee and clutches the edge. Rather than leap, he tests the light with one trembling hand.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-109","variant":"original","source":"original","n":108,"seq":109,"total":null,"start":1605,"end":1620,"timecode":"26:45-27:00","track":null,"act":"VI","actName":"NO GRAND AWAKENING","beat":"","setting":"","camera":"","prompt":"His hand passes through. For the first time, the light does not retreat. He closes his eyes, takes one painful breath, and pulls himself forward.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-110","variant":"original","source":"original","n":109,"seq":110,"total":null,"start":1620,"end":1635,"timecode":"27:00-27:15","track":null,"act":"VI","actName":"NO GRAND AWAKENING","beat":"","setting":"","camera":"","prompt":"Behind him, the cathedral, forest, desert, and hospital overlap in a collapsing panorama. Figments stand in distant doorways, not waving or pleading. They simply watch until their outlines blur.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-111","variant":"original","source":"original","n":110,"seq":111,"total":null,"start":1635,"end":1650,"timecode":"27:15-27:30","track":null,"act":"VI","actName":"NO GRAND AWAKENING","beat":"","setting":"","camera":"","prompt":"He crawls through the slit. His coat catches on the wall; he leaves a long strip behind. The light fills the frame, dirty white with visible film grain, not a clean digital glow.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-112","variant":"original","source":"original","n":111,"seq":112,"total":null,"start":1650,"end":1665,"timecode":"27:30-27:45","track":null,"act":"VI","actName":"NO GRAND AWAKENING","beat":"","setting":"","camera":"","prompt":"Sound drops to near silence. A single inhale, a pause, then an exhale. The camera holds on the pale frame long enough for discomfort to set in.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-113","variant":"original","source":"original","n":112,"seq":113,"total":null,"start":1665,"end":1680,"timecode":"27:45-28:00","track":null,"act":"VI","actName":"NO GRAND AWAKENING","beat":"","setting":"","camera":"","prompt":"Cut to black. A fluorescent hum continues. After several seconds, a monitor beeps once, then returns to its uneven rhythm. No title card, no explanation.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null},{"id":"original-114","variant":"original","source":"original","n":113,"seq":114,"total":null,"start":1680,"end":1695,"timecode":"28:00-28:15","track":null,"act":"VI","actName":"NO GRAND AWAKENING","beat":"","setting":"","camera":"","prompt":"Final image: on a black field, the words FEVER DREAM appear in distressed ochre lettering, edges fraying like old film emulsion. One faint violet pulse travels through the letters, then dies. Final production critique checklist ● Does the man's coat, injuries, carried objects, and fatigue persist from clip to clip? ● Does every Figment create a specific interaction rather than merely pose as a monster? ● Are there no more than one or two dominant visual ideas in any 15-second generation? ● Do cuts preserve screen direction, light direction, and the man's physical position whenever possible? ● Is the final waking state deliberately unresolved, with no explanatory voice-over or tidy cure? ● If a generated clip looks too polished, too colorful, or too clean, regenerate it rather than accepting a break in the analog texture.","action":"","audio":"","subtext":"","narrative":"","structure":"","trackA":"","trackB":"","bridge":"","anchor":"","unified":"","anomaly":null}];
